gVT(){return"\u0928\u094b\u091f\u093f\u092b\u093f\u0915\u0947\u0936\u0928 \u090f\u0915\u094d\u0938\u0947\u0938"},
gVA(){return"\u0905\u0928\u0941\u092e\u0924\u093f \u0926\u0940 \u0917\u0908"},
